    def sum_of_digits(n):
        if n < 0:
            return -sum_of_digits(-n)
        if n == 0:
            return 0
        return n % 10 + sum_of_digits(n // 10)

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count

